import sys
import re
import collections


CANDIDATES = [
    # (pos, allowed bases, ordered alleles used to assign a starting phase)
    (27079306, {"C", "A"}, ["C", "A"]),
    (27079366, {"T", "C"}, ["T", "C"]),
    (27079666, {"A", "T"}, ["A", "T"]),
    (27080076, {"C", "G"}, ["C", "G"]),
    (27080526, {"G", "A"}, ["G", "A"]),
]


def parse_cigar(cigar):
    return [(int(n), op) for n, op in re.findall(r"(\d+)([MIDNSHP=X])", cigar)]


def alleles_on_read(target, read_start, cigar, seq, qual):
    """Yield base->quality votes for one candidate target position on one read."""
    refpos = read_start
    qpos = 0
    for n, op in parse_cigar(cigar):
        if op in ("M", "=", "X"):
            for _ in range(n):
                if refpos == target and qpos < len(seq):
                    base = seq[qpos].upper()
                    q = ord(qual[qpos]) - 33 if qpos < len(qual) else 0
                    yield base, max(q, 1)
                refpos += 1

